INSERT OR REPLACE INTO products (id, category, look, price_now, price_old, default_size, active, sort, availability, product_type, unit) VALUES ('lampa-nova', 'lighting', 'lampa-nova', 401047, 0, 0, 1, 14, 'in_stock', 'simple', 'pcs');
