INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-nova', 'ru', 'Настольная лампа «NOVA»', 'Настольные лампы', 'Настольная лампа NOVA (235×309 мм) на архитектурном штативе-треноге. Органический плафон со скруглённым квадратным куполом и фактурным рельефом мягко рассеивает тёплый вечерний свет. Чёрные наклонные ножки обеспечивают устойчивость светильника на тумбе, консоли или рабочем столе, создавая стильный световой акцент.', '["23,5 × 30,9 см"]', '{"mat":"металл, акрил, LED","dim":"23,5 × 30,9 см","maxLoad":"","colors":"Белый с чёрным основанием"}', 'Купить Настольная лампа «NOVA» в Ташкенте - BTT', 'Настольная лампа «NOVA» от BTT. Мягкое тёплое освещение, органический купол, ножки-тренога. Размеры: 23,5 × 30,9 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-nova', 'uz', '«NOVA» stol lampasi', 'Stol lampalari', 'Qora uchoyoqli me’moriy asosdagi NOVA stol lampasi (235×309 mm). Dumaloqlangan to‘rtburchak shaklidagi relyefli gumbazi iliq oqshom nurini muloyim taratadi. Qiya oyoqchalari chiroqning tumba, konsol yoki ish stolida mustahkam turishini ta’minlaydi.', '["23,5 × 30,9 см"]', '{"mat":"металл, акрил, LED","dim":"23,5 × 30,9 см","maxLoad":"","colors":"Qora asosli oq"}', 'Toshkentda «NOVA» stol lampasi sotib olish - BTT', 'BTT dan «NOVA» stol lampasi. Yumshoq iliq nur, relyefli gumbaz, uchoyoqli asos. O‘lchamlari: 23,5 × 30,9 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-nova', 'en', 'NOVA Table Lamp', 'Table lamps', 'NOVA table lamp (235×309 mm) elevated on an architectural black tripod base. The organic square-rounded shade with horizontal texturing gently diffuses warm evening light. Angled tripod feet lend stability and understated sculptural presence to consoles, bedside tables, and desks.', '["23,5 × 30,9 см"]', '{"mat":"металл, акрил, LED","dim":"23,5 × 30,9 см","maxLoad":"","colors":"White with black base"}', 'Buy NOVA Table Lamp in Tashkent - BTT', 'NOVA Table Lamp by BTT. Warm ambient illumination, organic square-rounded shade, black tripod base. Dimensions: 23.5 × 30.9 cm. Delivery across Tashkent and Uzbekistan.');
