INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-sora', 'ru', 'Настольная лампа «SORA»', 'Настольные лампы', 'Настольная лампа SORA (250×430 мм) в гармоничной двухъярусной геометрии. Цилиндрический плафон с волнообразным каннелированным рельефом опирается на сферическое спиральное основание. Светильник мягко светится обоими объёмами, наполняя интерьер спальни или гостиной глубоким тёплым светом и скульптурной эстетикой.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"Белый"}', 'Купить Настольная лампа «SORA» в Ташкенте - BTT', 'Настольная лампа «SORA» от BTT. Мягкое тёплое освещение, двухъярусная скульптурная форма. Размеры: 25 × 43 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-sora', 'uz', '«SORA» stol lampasi', 'Stol lampalari', 'Mukammal ikki qismli geometriyaga ega SORA stol lampasi (250×430 mm). To‘lqinsimon naqshli silindrsimon qopqog‘i spiral sharsimon asos bilan uyg‘unlashgan. Har ikki qismi ham muloyim nur taratib, yotoqxona yoki mehmonxonaga iliq sokinlik va estetik joziba bag‘ishlaydi.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"Oq"}', 'Toshkentda «SORA» stol lampasi sotib olish - BTT', 'BTT dan «SORA» stol lampasi. Yumshoq iliq nur, ikki qismli skulptur shakl. O‘lchamlari: 25 × 43 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-sora', 'en', 'SORA Table Lamp', 'Table lamps', 'SORA table lamp (250×430 mm) featuring a balanced two-tier composition. A wave-fluted cylindrical upper shade perches upon a spherical spiral-ribbed glowing base. Both sculpted volumes illuminate with warm ambient light, turning any living room console or bedside table into an artful sanctuary.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"White"}', 'Buy SORA Table Lamp in Tashkent - BTT', 'SORA Table Lamp by BTT. Warm ambient illumination, two-tier sculptural silhouette. Dimensions: 25 × 43 cm. Delivery across Tashkent and Uzbekistan.');
