INSERT OR REPLACE INTO products (id, category, look, price_now, price_old, default_size, active, sort, availability, product_type, unit) VALUES ('lampa-vela', 'lighting', 'lampa-vela', 332252, 0, 0, 1, 16, 'in_stock', 'simple', 'pcs');
