INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-vela', 'ru', 'Настольная лампа «VELA»', 'Настольные лампы', 'Настольная лампа VELA (250×430 мм) в стиле скульптурного биоморфизма. Выразительный вихревой плафон с рельефной фактурой мягко рассеивает тёплый вечерний свет, создавая атмосферу уюта и гармонии. Контрастное основание в виде чёрной каннелированной колонны придаёт светильнику архитектурную устойчивость. Идеально смотрится на консоли, журнальном столике или прикроватной тумбе.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"Белый с чёрным основанием"}', 'Купить Настольная лампа «VELA» в Ташкенте - BTT', 'Настольная лампа «VELA» от BTT. Мягкое тёплое освещение, скульптурный вихревой плафон, чёрное основание. Размеры: 25 × 43 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-vela', 'uz', '«VELA» stol lampasi', 'Stol lampalari', 'Skulptur biomorfizm uslubidagi VELA stol lampasi (250×430 mm). Relyefli to‘lqinsimon gumbazi yumshoq iliq oqshom nurini taratib, xonada shinam va sokin muhit yaratadi. Qora rangli qirrali silindr asosi chiroqqa mustahkam me’moriy ko‘rinish beradi. Konsol, kofe stoli yoki yotoqxona tumbasi uchun ajoyib tanlov.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"Qora asosli oq"}', 'Toshkentda «VELA» stol lampasi sotib olish - BTT', 'BTT dan «VELA» stol lampasi. Yumshoq iliq nur, skulptur to‘lqinsimon plafon, qora asos. O‘lchamlari: 25 × 43 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-vela', 'en', 'VELA Table Lamp', 'Table lamps', 'VELA table lamp (250×430 mm) in sculptural biomorphic design. The expressive swirling shade with textured fluting gently diffuses warm evening light, cultivating an atmosphere of cozy serenity. A contrasting fluted black column base provides architectural presence. Ideal for accent consoles, coffee tables, and bedside nightstands.', '["25 × 43 см"]', '{"mat":"металл, акрил, LED","dim":"25 × 43 см","maxLoad":"","colors":"White with black base"}', 'Buy VELA Table Lamp in Tashkent - BTT', 'VELA Table Lamp by BTT. Warm ambient lighting, sculptural swirling shade, black reeded base. Dimensions: 25 × 43 cm. Delivery across Tashkent and Uzbekistan.');
