INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-runa', 'ru', 'Настольная лампа «RUNA»', 'Настольные лампы', 'Настольная лампа RUNA (190×223 мм) в стиле органического минимализма. Фактурный корпус со спиральным рельефом мягко рассеивает тёплый вечерний свет, наполняя пространство домашним уютом. Устойчивое основание на ножках гармонично смотрится на журнальном столике, консоли, прикроватной тумбе или открытых полках.', '["19 × 22,3 см"]', '{"mat":"металл, акрил, LED","dim":"19 × 22,3 см","maxLoad":"","colors":"Белый"}', 'Купить Настольная лампа «RUNA» в Ташкенте - BTT', 'Настольная лампа «RUNA» от BTT. Мягкое тёплое освещение, спиральный рельеф. Размеры: 19 × 22,3 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-runa', 'uz', '«RUNA» stol lampasi', 'Stol lampalari', 'Organik minimalizm uslubidagi RUNA stol lampasi (190×223 mm). Spiral naqshli korpusi iliq kechki nurni muloyim taratib, xonada shinam va sokin muhit yaratadi. Uchoyoqli barqaror asosi kofe stoli, yotoqxona tumbasi yoki dekorativ tokchalarda mukammal ko‘rinadi.', '["19 × 22,3 см"]', '{"mat":"металл, акрил, LED","dim":"19 × 22,3 см","maxLoad":"","colors":"Oq"}', 'Toshkentda «RUNA» stol lampasi sotib olish - BTT', 'BTT dan «RUNA» stol lampasi. Yumshoq iliq nur, spiral relyef. O‘lchamlari: 19 × 22,3 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-runa', 'en', 'RUNA Table Lamp', 'Table lamps', 'RUNA table lamp (190×223 mm) in organic minimalist design. The tactile spiral-fluted body gently diffuses warm ambient light, creating a serene and cozy atmosphere. Supported by tripod feet, it sits effortlessly on bedside tables, accent consoles, and coffee tables.', '["19 × 22,3 см"]', '{"mat":"металл, акрил, LED","dim":"19 × 22,3 см","maxLoad":"","colors":"White"}', 'Buy RUNA Table Lamp in Tashkent - BTT', 'RUNA Table Lamp by BTT. Warm ambient illumination with spiral-fluted texture. Dimensions: 19 × 22.3 cm. Delivery across Tashkent and Uzbekistan.');
