INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-liva', 'ru', 'Настольная лампа «LIVA»', 'Настольные лампы', 'Настольная лампа LIVA (120×248 мм) в форме изящной спиральной колонны с динамичными рёбрами. Компактный вертикальный силуэт на тёмном квадратном основании создаёт мягкий рассеянный свет, идеально подходящий для акцентной подсветки журнальных столиков, прикроватных тумб, полок и интерьеров кафе.', '["12 × 24,8 см"]', '{"mat":"металл, акрил, LED","dim":"12 × 24,8 см","maxLoad":"","colors":"Белый, Мятный"}', 'Купить Настольная лампа «LIVA» в Ташкенте - BTT', 'Настольная лампа «LIVA» от BTT. Мягкое тёплое освещение, спиральная колонна с тонкими рёбрами. Размеры: 12 × 24,8 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-liva', 'uz', '«LIVA» stol lampasi', 'Stol lampalari', 'Dinamik qirrali nafis spiral ustun shaklidagi LIVA stol lampasi (120×248 mm). Qora kvadrat asosdagi ixcham vertikal silueti kofe stoli, yotoqxona tumbasi yoki javonlar uchun tarqoq yumshoq nur hosil qiladi.', '["12 × 24,8 см"]', '{"mat":"металл, акрил, LED","dim":"12 × 24,8 см","maxLoad":"","colors":"Oq, Yalpiz"}', 'Toshkentda «LIVA» stol lampasi sotib olish - BTT', 'BTT dan «LIVA» stol lampasi. Yumshoq iliq nur, nafis spiral ustun. O‘lchamlari: 12 × 24,8 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-liva', 'en', 'LIVA Table Lamp', 'Table lamps', 'LIVA table lamp (120×248 mm) shaped as an elegant twisting fluted column. Rising gracefully from a dark square pedestal, its slender vertical silhouette diffuses gentle ambient lighting ideal for nightstands, coffee tables, shelving, and boutique hospitality settings.', '["12 × 24,8 см"]', '{"mat":"металл, акрил, LED","dim":"12 × 24,8 см","maxLoad":"","colors":"White, Mint"}', 'Buy LIVA Table Lamp in Tashkent - BTT', 'LIVA Table Lamp by BTT. Warm ambient illumination, twisting fluted column silhouette. Dimensions: 12 × 24.8 cm. Delivery across Tashkent and Uzbekistan.');
