INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-aria', 'ru', 'Настольная лампа «ARIA»', 'Настольные лампы', 'Настольная лампа ARIA (118×243,5 мм) с волнообразными вертикальными лепестками на тёплом деревянном основании. Тонкие пластины мягко направляют световой поток изнутри, создавая игру полутеней и уютную атмосферу для вечернего чтения, отдыха и умиротворения.', '["11,8 × 24,35 см"]', '{"mat":"металл, акрил, LED","dim":"11,8 × 24,35 см","maxLoad":"","colors":"Белый с деревом"}', 'Купить Настольная лампа «ARIA» в Ташкенте - BTT', 'Настольная лампа «ARIA» от BTT. Мягкое тёплое освещение, волнообразные лепестки, деревянное основание. Размеры: 11,8 × 24,35 см. Доставка по Ташкенту и всему Узбекистану.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-aria', 'uz', '«ARIA» stol lampasi', 'Stol lampalari', 'Yog‘och asosli to‘lqinsimon vertikal qirralarga ega ARIA stol lampasi (118×243,5 mm). Ichki iliq nur nozik qirralar orasidan mayin taralib, xonada oqshomgi mutolaa va dam olish uchun sokin yoqimli muhit yaratadi.', '["11,8 × 24,35 см"]', '{"mat":"металл, акрил, LED","dim":"11,8 × 24,35 см","maxLoad":"","colors":"Oq yog‘ochli"}', 'Toshkentda «ARIA» stol lampasi sotib olish - BTT', 'BTT dan «ARIA» stol lampasi. Yumshoq iliq nur, vertikal to‘lqinli qirralar, yog‘och asos. O‘lchamlari: 11,8 × 24,35 sm. Toshkent va butun O‘zbekiston bo‘ylab yetkazib berish.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('lampa-aria', 'en', 'ARIA Table Lamp', 'Table lamps', 'ARIA table lamp (118×243.5 mm) enveloped in undulating vertical ribbons upon a rich wooden pedestal. Light filters gently through the vertical fins, casting soft shadows and serene warmth across bedside tables, desks, and reading nooks.', '["11,8 × 24,35 см"]', '{"mat":"металл, акрил, LED","dim":"11,8 × 24,35 см","maxLoad":"","colors":"White with wooden base"}', 'Buy ARIA Table Lamp in Tashkent - BTT', 'ARIA Table Lamp by BTT. Warm ambient illumination, undulating vertical ribbons, wooden base. Dimensions: 11.8 × 24.35 cm. Delivery across Tashkent and Uzbekistan.');
