INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('rotang-polutrubka', 'ru', 'Искусственный ротанг - профиль Полутрубка', 'Искусственный ротанг', 'Искусственный ротанг BTT, профиль «Полутрубка» из первичного полимера. Полукруглое сечение для плетения мебели, кашпо и элементов декора. Поставляется в бухтах под заказ от минимального объёма (MOQ).', '["Бухты / бобины"]', '{"mat":"первичный полимер, УФ-стабилизатор","dim":"Бухты / бобины","maxLoad":"","colors":"Шоколадный"}', 'Искусственный ротанг Полутрубка оптом в Ташкенте - BTT', 'Искусственный ротанг BTT профиль Полутрубка. Производство плетёной мебели в Ташкенте.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('rotang-polutrubka', 'uz', 'Sun‘iy rotang - Yarim trubka profili', 'Sun‘iy rotang', 'BTT sun''iy rotangi, birlamchi polimerdan tayyorlangan «Yarim naycha» profili. Mebel, gultuvak va bezak buyumlarini to‘qish uchun yarim aylana kesim. Minimal hajm (MOQ) asosida buyurtma bo‘yicha yetkaziladi.', '["Бухты / бобины"]', '{"mat":"первичный полимер, УФ-стабилизатор","dim":"Бухты / бобины","maxLoad":"","colors":"Shokolad"}', 'Toshkentda sun‘iy rotang Yarim trubka - BTT', 'BTT dan sun‘iy rotang Yarim trubka profili. Toshkentda to‘qilgan mebel ishlab chiqarish uchun.');
