INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('komplekt-vertex-d90-vertex', 'ru', 'Комплект: Круглый стол Vertex D90 + 4 плетёных стула Vertex', 'Комплекты мебели', 'Готовый обеденный гарнитур BTT: круглый стол Vertex D90 со столешницей под белый мрамор и 4 плетёных стула Vertex из кручёного искусственного ротанга с мягкими подушками. Элегантное решение для столовой, закрытой веранды или загородного дома по специальной фабричной цене.', '["Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см"]', '{"mat":"металл, кручёный искусственный ротанг, ЛДСП мрамор, текстиль","dim":"Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см","maxLoad":"","colors":"Белый мрамор / Бежевый"}', 'Комплект стол Vertex D90 и 4 стула Vertex - купить в Ташкенте BTT', 'Готовый комплект: круглый стол Vertex D90 и 4 плетёных стула Vertex с подушками по спеццене 2 676 000 сум от производителя BTT в Ташкенте.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('komplekt-vertex-d90-vertex', 'uz', 'To''plam: Yumaloq stol Vertex D90 + 4 ta to''qilgan Vertex stuli', 'Mebel to‘plamlari', 'BTT tayyor tushlik to''plami: oq marmar naqshli yumaloq stol Vertex D90 va yumshoq yostiqli 4 ta o''rilgan rotangli Vertex stuli. Fabrika maxsus narxida.', '["Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см"]', '{"mat":"металл, кручёный искусственный ротанг, ЛДСП мрамор, текстиль","dim":"Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см","maxLoad":"","colors":"Oq marmar / Bej"}', 'Vertex D90 stoli va 4 ta Vertex stuli to''plami - Toshkentda BTT', 'Tayyor to''plam: Vertex D90 stoli va 4 ta Vertex stuli 2 676 000 so''m maxsus narxda.');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs, seo_title, seo_description) VALUES ('komplekt-vertex-d90-vertex', 'en', 'Dining Set: Round Table Vertex D90 + 4 Vertex Wicker Chairs', 'Furniture sets', 'Ready-to-use BTT dining set: round Vertex D90 table with white marble finish and 4 Vertex twisted rattan chairs with plush cushions. Factory special package price.', '["Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см"]', '{"mat":"металл, кручёный искусственный ротанг, ЛДСП мрамор, текстиль","dim":"Стол Ø90 × 75 см, 4 стула 57 × 63 × 75 см","maxLoad":"","colors":"White marble / Beige"}', 'Vertex D90 Table + 4 Vertex Chairs Dining Set - BTT Tashkent', 'Buy dining set: round table Vertex D90 + 4 Vertex wicker chairs for 2,676,000 UZS by BTT.');
